// 1. Ambil data
const inputData = items[0].json.body;
const reviews = inputData.reviews || [];
const meta = inputData.meta || {};

// Helper Clean Text
const cleanText = (text) => {
  if (!text || typeof text !== 'string' || text.trim() === "" || text === "-") return null;
  return text.trim().replace(/^"|"$/g, '').replace(/\\"/g, '"');
};

// 2. Variable Penampung Skor
let grandTotalScore = 0; 
let count = 0;

// Penampung per kategori (SUM)
let totalQ = 0, totalRel = 0, totalCom = 0, totalIni = 0, totalLead = 0;

let feedbackRaw = `Employee ID: ${meta.reviewee_id}\n`;
feedbackRaw += `Total Review: ${reviews.length} Orang\n\n`;

if (reviews.length === 0) {
  feedbackRaw += "BELUM ADA DATA.\n";
} else {
  reviews.forEach((r, index) => {
    // Ambil nilai per kategori (default 0 jika null)
    const q = Number(r.score_quality || 0);
    const rel = Number(r.score_reliability || 0);
    const com = Number(r.score_communication || 0);
    const ini = Number(r.score_initiative || 0);
    const lead = Number(r.score_leadership || 0);

    // Akumulasi per kategori (TOTAL)
    totalQ += q; totalRel += rel; totalCom += com; totalIni += ini; totalLead += lead;

    // Akumulasi ke Grand Total (Sum semua nilai 5 kategori)
    grandTotalScore += (q + rel + com + ini + lead);

    count++;

    // --- SUSUN TEKS UTK AI ---
    // Reviewers stay anonymous: no name or job title reaches the AI.
    feedbackRaw += `### Rekan #${index + 1}\n`;

    // Opsional: Tampilkan skor perorangan ke AI kalau butuh konteks detail
    feedbackRaw += `SCORES: Q:${q} | Rel:${rel} | Com:${com} | Ini:${ini} | Lead:${lead}\n`;

    // Alasan
    const reasons = [
      r.justification_quality, r.justification_reliability, 
      r.justification_communication, r.justification_initiative, 
      r.justification_leadership
    ].map(cleanText).filter(Boolean);

    if (reasons.length > 0) feedbackRaw += `REASONS: ${reasons.join(' | ')}\n`;

    // Feedback
    const start = cleanText(r.feedback_start);
    const cont = cleanText(r.feedback_continue);
    const stop = cleanText(r.feedback_stop);

    if (start) feedbackRaw += `> START: ${start}\n`;
    if (cont)  feedbackRaw += `> CONTINUE: ${cont}\n`;
    if (stop)  feedbackRaw += `> STOP: ${stop}\n`;

    feedbackRaw += `\n`;
  });
}

// 3. RUMUS PERHITUNGAN GLOBAL
const averageTotalPerPerson = count > 0 ? (grandTotalScore / count) : 0;
const averageScore5 = Number((averageTotalPerPerson / 5).toFixed(2));
const percentage = Math.round((averageScore5 / 5) * 100);


// --- UPDATE LOGIKA DI SINI ---
// Helper hitung rata-rata per kategori (1 desimal)
const calcAvg = (totalSum, totalUser) => {
    if (totalUser === 0) return 0;
    // toFixed(1) bikin string "5.3", Number() balikin jadi angka 5.3
    return Number((totalSum / totalUser).toFixed(1));
};

// 4. Output Data Scores (SEKARANG SUDAH RATA-RATA)
const finalScores = {
  quality_of_work: calcAvg(totalQ, count),
  reliability_deadline: calcAvg(totalRel, count),
  communication: calcAvg(totalCom, count),
  initiative_growth: calcAvg(totalIni, count),
  leadership_teamwork: calcAvg(totalLead, count)
};

// Tambahkan info ini ke teks prompt untuk konteks AI
feedbackRaw += `=== STATISTIK FINAL ===\n`;
feedbackRaw += `Total Score All Users: ${grandTotalScore}\n`;
feedbackRaw += `Average Score (Scale 5): ${averageScore5}\n`;
feedbackRaw += `Percentage: ${percentage}%\n`;

// 5. Output Akhir
return [
  {
    json: {
      prompt_text: feedbackRaw,
      scores: finalScores, // Data Angka (Sudah Rata-rata 1 desimal)
      overall_result: {
        average_score: averageScore5, 
        percentage: percentage,
        total_user: count
      },
      reviewee_id: meta.reviewee_id,
      cycle_id: meta.cycle_id
    }
  }
];

